class Solution:
    def discountPrices(self, sentence: str, discount: int) -> str:
        out = []
        for w in sentence.split(' '):
            if len(w) > 1 and w[0] == '$' and w[1:].isdigit():
                p = int(w[1:]) * (100 - discount) / 100
                out.append('$%.2f' % p)
            else:
                out.append(w)
        return ' '.join(out)

