class Solution {
public:
    string discountPrices(string sentence, int discount) {
        istringstream in(sentence);
        ostringstream out;
        string w;
        bool first = true;
        while (in >> w) {
            bool price = w.size() > 1 && w[0] == '$';
            for (size_t i = 1; i < w.size() && price; i++) price = isdigit(w[i]);
            if (price) {
                double p = stoll(w.substr(1)) * (100 - discount) / 100.0;
                char buf[32];
                snprintf(buf, sizeof(buf), "$%.2f", p);
                w = buf;
            }
            if (!first) out << ' ';
            first = false;
            out << w;
        }
        return out.str();
    }
};

