class Solution {
    public String discountPrices(String sentence, int discount) {
        StringBuilder sb = new StringBuilder();
        for (String w : sentence.split(" ")) {
            boolean price = w.length() > 1 && w.charAt(0) == '$';
            for (int i = 1; i < w.length() && price; i++) price = Character.isDigit(w.charAt(i));
            if (price) {
                double p = Long.parseLong(w.substring(1)) * (100 - discount) / 100.0;
                sb.append(String.format("$%.2f", p));
            } else sb.append(w);
            sb.append(' ');
        }
        sb.setLength(Math.max(0, sb.length() - 1));
        return sb.toString();
    }
}

