// C++ std::regex lacks lambda replacement; the token-scan approach (see other tab) is idiomatic.
class Solution {
public:
    string discountPrices(string sentence, int discount) {
        string res;
        size_t i = 0, n = sentence.size();
        while (i < n) {
            size_t j = sentence.find(' ', i);
            if (j == string::npos) j = n;
            string w = sentence.substr(i, j - i);
            bool price = w.size() > 1 && w[0] == '$';
            for (size_t k = 1; k < w.size() && price; k++) price = isdigit(w[k]);
            if (!res.empty()) res += ' ';
            if (price) {
                char buf[32];
                snprintf(buf, sizeof(buf), "$%.2f", stoll(w.substr(1)) * (100 - discount) / 100.0);
                res += buf;
            } else res += w;
            i = j + 1;
        }
        return res;
    }
};

