class Solution {
    public String discountPrices(String sentence, int discount) {
        StringBuffer sb = new StringBuffer();
        Matcher m = Pattern.compile("\\$(\\d+)(?![\\w$])").matcher(sentence);
        while (m.find()) {
            double p = Long.parseLong(m.group(1)) * (100 - discount) / 100.0;
            m.appendReplacement(sb, String.format("$%.2f", p));
        }
        m.appendTail(sb);
        return sb.toString();
    }
}

